/** Runs every step in order. */
export async function runFlow(page: Page, vars: Vars): Promise<Outputs> {
  const outputs: Outputs = {};
  await page.goto('http://127.0.0.1:8085/');
  await steps['01-open'](page, { v1: 'http://127.0.0.1:8085/' }, outputs);
  await steps['02-create'](page, { v1: vars.runid, v2: `${vars.runid} Bench Task`, v3: `Bench task for run ${vars.runid}` }, outputs);
  await steps['03-verify'](page, { v1: vars.runid }, outputs);
  await steps['04-open'](page, { v1: vars.runid, v2: `${vars.runid} Bench Task`, v3: `Comment for run ${vars.runid}` }, outputs);
  await steps['05-open'](page, { v1: vars.runid, v2: `${vars.runid} Bench Task` }, outputs);
  return outputs;
}
